/**
 * Typed game-knowledge lookup over distilled Data Dragon data
 * (packages/shared/data, regenerated by scripts/fetch-ddragon.mjs).
 * Pure + browser-safe: JSON is bundled, no fs access.
 */
import championData from "../data/champions.json" with { type: "json" };
import itemData from "../data/items.json" with { type: "json" };

export type ChampTag = "Fighter" | "Tank" | "Mage" | "Assassin" | "Marksman" | "Support";
export type DamageType = "AP" | "AD" | "TANK";

export interface ChampionInfo {
  id: string;
  key: number;
  name: string;
  title: string;
  tags: string[];
  resource: string;
  range: number;
  info: { attack: number; defense: number; magic: number; difficulty: number };
  stats: {
    hp: number; hpLvl: number; armor: number; armorLvl: number; mr: number; mrLvl: number;
    ad: number; adLvl: number; as: number; asLvl: number; ms: number;
  };
  passive: { name: string; desc: string };
  spells: { slot: string; name: string; desc: string }[];
}

export interface ItemInfo {
  id: string;
  name: string;
  cost: number;
  tier: "starter" | "component" | "boots" | "legendary";
  tags: string[];
  stats: Record<string, number>;
  from: string[];
  into: string[];
  passives: string[];
  flags: string[];
}

type RawChamps = { version: string; champions: Record<string, Omit<ChampionInfo, "id">> };
type RawItems = { version: string; items: Record<string, Omit<ItemInfo, "id">> };

const CH = championData as unknown as RawChamps;
const IT = itemData as unknown as RawItems;

export const DDRAGON_VERSION = CH.version;

export function normKey(s: string | undefined | null): string {
  return String(s ?? "").toLowerCase().replace(/[^a-z0-9]/g, "");
}

const champIndex = new Map<string, ChampionInfo>();
for (const [id, c] of Object.entries(CH.champions)) {
  const full: ChampionInfo = { id, ...c };
  champIndex.set(normKey(id), full);
  champIndex.set(normKey(c.name), full);
  champIndex.set(String(c.key), full);
}

const itemById = new Map<string, ItemInfo>();
const itemByName = new Map<string, ItemInfo>();
for (const [id, it] of Object.entries(IT.items)) {
  const full: ItemInfo = { id, ...it };
  itemById.set(id, full);
  const k = normKey(it.name);
  const prev = itemByName.get(k);
  // Duplicate names (mode variants): keep the lowest id (base SR item).
  if (!prev || Number(id) < Number(prev.id)) itemByName.set(k, full);
}

export function getChampion(nameOrId: string | number | undefined | null): ChampionInfo | null {
  if (nameOrId == null) return null;
  return champIndex.get(typeof nameOrId === "number" ? String(nameOrId) : normKey(nameOrId)) ?? null;
}

export function getItem(idOrName: string | number | undefined | null): ItemInfo | null {
  if (idOrName == null) return null;
  const s = String(idOrName);
  return itemById.get(s) ?? itemByName.get(normKey(s)) ?? null;
}

export function allChampionIds(): string[] {
  return Object.keys(CH.champions);
}

export function allItems(): ItemInfo[] {
  return [...itemById.values()];
}

/** Completed (legendary) item = power spike visible on the scoreboard. */
export function isCompletedItem(it: ItemInfo | null): boolean {
  return !!it && it.tier === "legendary" && it.cost >= 2200;
}

/** Champion base damage profile from tags + DDragon info ratings. */
export function champDamageType(champ: ChampionInfo | null): DamageType {
  if (!champ) return "AD";
  const { attack, magic, defense } = champ.info;
  if (champ.tags[0] === "Tank" || (champ.tags.includes("Tank") && defense >= 8 && attack < 6 && magic < 6)) {
    return "TANK";
  }
  if (magic === attack) return champ.tags[0] === "Mage" || champ.tags.includes("Mage") ? "AP" : "AD";
  return magic > attack ? "AP" : "AD";
}

/** Damage type adjusted by what they actually bought (scoreboard-visible). */
export function threatTypeFor(champName: string, items: (string | number)[] = []): DamageType {
  const champ = getChampion(champName);
  let ap = 0, ad = 0, tank = 0;
  for (const i of items) {
    const it = getItem(i);
    if (!it || it.cost < 900) continue;
    ap += it.stats.ap ?? 0;
    ad += (it.stats.ad ?? 0) + (it.stats.crit ?? 0) * 100 + (it.stats.as ?? 0) * 60;
    tank += (it.stats.armor ?? 0) + (it.stats.mr ?? 0) + (it.stats.hp ?? 0) / 8;
  }
  const base = champDamageType(champ);
  if (ap + ad + tank < 60) return base;
  if (tank > (ap + ad) * 1.4) return "TANK";
  if (ap > ad * 1.3) return "AP";
  if (ad > ap * 1.3) return "AD";
  return base;
}

function kitText(c: ChampionInfo): string {
  return [c.passive.desc, ...c.spells.map((s) => s.desc)].join(" ").toLowerCase();
}

export function champHeals(c: ChampionInfo | null): boolean {
  return !!c && /\bheal(s|ing|ed)?\b|restor\w* (\w+ )?health|life steal|steals? (\w+ )?life|omnivamp|drains?\b/.test(kitText(c));
}

export function champShields(c: ChampionInfo | null): boolean {
  return !!c && /\bshield/.test(kitText(c));
}

/** Legendary items with a given stat that also fit your damage profile. */
export function itemOptionsFor(
  stat: "armor" | "mr" | "antiheal",
  myProfile: DamageType,
  limit = 2
): string[] {
  const fits = (it: ItemInfo) =>
    myProfile === "AP" ? (it.stats.ap ?? 0) > 0 : myProfile === "AD" ? (it.stats.ad ?? 0) > 0 || (it.stats.crit ?? 0) > 0 : (it.stats.hp ?? 0) > 0;
  const pool = allItems().filter((it) => it.tier === "legendary" && it.cost >= 2200);
  const want = pool.filter((it) =>
    stat === "antiheal" ? it.flags.includes("antiheal") : (it.stats[stat] ?? 0) >= 20
  );
  const ranked = [...want.filter(fits), ...want.filter((it) => !fits(it))];
  const seen = new Set<string>();
  const out: string[] = [];
  for (const it of ranked) {
    if (seen.has(it.name)) continue;
    seen.add(it.name);
    out.push(it.name);
    if (out.length >= limit) break;
  }
  return out;
}

export interface MatchupCard {
  you: string;
  youType: DamageType;
  youRange: number | null;
  opponent?: string;
  opponentType?: DamageType;
  opponentRange?: number | null;
  rangeNote?: string;
  threats: { AP: number; AD: number; TANK: number };
  healers: string[];
  shielders: string[];
  itemNotes: string[];
  opponentKit?: string;
}

export interface MatchupInput {
  you: string;
  youItems?: (string | number)[];
  opponent?: string;
  enemies: { championName: string; items?: (string | number)[] }[];
}

export function buildMatchupCard(inp: MatchupInput): MatchupCard {
  const me = getChampion(inp.you);
  const youType = threatTypeFor(inp.you, inp.youItems);
  const threats = { AP: 0, AD: 0, TANK: 0 };
  const healers: string[] = [];
  const shielders: string[] = [];
  for (const e of inp.enemies) {
    const t = threatTypeFor(e.championName, e.items);
    threats[t]++;
    const c = getChampion(e.championName);
    const label = c?.name ?? e.championName;
    if (champHeals(c)) healers.push(label);
    if (champShields(c)) shielders.push(label);
  }
  const opp = inp.opponent ? getChampion(inp.opponent) : null;
  const card: MatchupCard = {
    you: me?.name ?? inp.you,
    youType,
    youRange: me?.range ?? null,
    threats,
    healers,
    shielders,
    itemNotes: [],
  };
  if (inp.opponent) {
    card.opponent = opp?.name ?? inp.opponent;
    card.opponentType = threatTypeFor(inp.opponent, inp.enemies.find((e) => normKey(e.championName) === normKey(inp.opponent))?.items);
    card.opponentRange = opp?.range ?? null;
    if (me && opp) {
      const d = me.range - opp.range;
      card.rangeNote =
        Math.abs(d) < 75 ? "similar auto range" : d > 0 ? `you outrange by ${d}` : `they outrange you by ${-d}`;
      card.opponentKit = opp.spells.map((s) => `${s.slot} ${s.name}`).join(", ");
    }
  }
  const prof = youType === "TANK" ? "TANK" : youType;
  if (threats.AD >= 3) card.itemNotes.push(`${threats.AD} AD threats — armor items like ${itemOptionsFor("armor", prof).join(" or ")} are options.`);
  if (threats.AP >= 3) card.itemNotes.push(`${threats.AP} AP threats — magic resist like ${itemOptionsFor("mr", prof).join(" or ")} is an option.`);
  if (healers.length >= 2) card.itemNotes.push(`${healers.length} healers (${healers.slice(0, 3).join(", ")}) — anti-heal like ${itemOptionsFor("antiheal", prof, 1).join("")} is an option.`);
  if (threats.TANK >= 2) card.itemNotes.push(`${threats.TANK} tanks — penetration or %HP damage gets value.`);
  return card;
}

export function formatMatchupCard(c: MatchupCard): string {
  const lines = [
    `## MATCHUP CARD`,
    `YOU: ${c.you} (${c.youType}${c.youRange ? `, range ${c.youRange}` : ""})` +
      (c.opponent ? ` vs ${c.opponent} (${c.opponentType}${c.opponentRange ? `, range ${c.opponentRange}` : ""}; ${c.rangeNote ?? ""})` : ""),
    `ENEMY THREATS: AP ${c.threats.AP} · AD ${c.threats.AD} · TANK ${c.threats.TANK} | healers ${c.healers.length} · shielders ${c.shielders.length}`,
  ];
  if (c.opponentKit) lines.push(`OPP KIT: ${c.opponentKit}`);
  for (const n of c.itemNotes) lines.push(`ITEMS: ${n}`);
  return lines.join("\n");
}

/** Champ-select matchup card from LCU picks (no items yet). */
export function champSelectMatchup(cs: {
  myChampion?: string;
  myChampionId?: number;
  enemies?: string[];
  assignedPosition?: string;
} | null | undefined): MatchupCard | null {
  if (!cs) return null;
  const me = getChampion(cs.myChampion ?? null) ?? getChampion(cs.myChampionId ?? null);
  if (!me) return null;
  const enemies = (cs.enemies ?? []).filter(Boolean);
  const pos = String(cs.assignedPosition ?? "").toLowerCase();
  const wantTag =
    pos.startsWith("bot") ? "Marksman" : pos.startsWith("util") || pos.startsWith("sup") ? "Support" : pos.startsWith("mid") ? "Mage" : pos.startsWith("top") ? "Fighter" : me.tags[0];
  const opp = enemies.find((e) => getChampion(e)?.tags[0] === wantTag) ?? enemies.find((e) => getChampion(e)?.tags.includes(wantTag));
  return buildMatchupCard({ you: me.id, opponent: opp, enemies: enemies.map((e) => ({ championName: e })) });
}
